/*
 * Spoofed weather-sensor transmit encoder — round-trip evidence.
 *
 * The evidence here is SYNTHETIC: nothing was captured off air. Every frame is generated by the encoder under
 * test (dsp/tx-weather.ts) and then cross-checked against the app's OWN rtl_433 decoder — the Acurite
 * "Acurite-Tower" sensor, protocol number 40, in dsp/r433/devices/acurite.ts. That decoder only emits a
 * reading when the byte-sum check and the data-byte parity both come out clean, so any emission at all proves
 * the frame layout, the checksum and the parity agree end to end; the temperature and humidity it reports are
 * then compared against what was asked for.
 *
 * Two layers of proof, weakest assumption first:
 *   1. weatherFrame -> BitBuffer -> the acuriteTxr decoder (the decoder inverts on the wire, so the frame goes
 *      in inverted), asserting model, temperature at 0.1 °C and humidity for a spread of values.
 *   2. weatherPulses -> the app's own PWM slicer (pulseSlicerPwm) -> the same decoder, proving the OOK timing
 *      itself decodes; and, independently, the pulses decoded back into bits here and compared to the frame.
 *
 * Beyond the happy path, each wire rule is checked at its PREMISE, and the encoder is mutated eight ways with
 * a local reference builder that is first shown to reproduce the real module byte-for-byte — so a mutation
 * that breaks the decode is proof the corresponding rule is load-bearing, not an artifact of the test.
 * tx-weather.ts duplicates the sum and parity on purpose; if either side drifts, the round trip stops
 * decoding and this file goes red.
 */
import { BitBuffer } from '../dist/dsp/r433/bitbuffer.js';
import { REGISTRY } from '../dist/dsp/r433/device.js';
import '../dist/dsp/r433/devices/index.js';                 // side-effect registration of every decoder
import { pulseSlicerPwm } from '../dist/dsp/r433/slicers.js';
import {
  WEATHER_MODEL, WEATHER_PROTOCOL, WEATHER_FREQ_HZ, weatherFrame, weatherPulses,
} from '../dist/dsp/tx-weather.js';

let pass = 0, fail = 0;
const ok = (c, what, extra = '') => { if (c) { pass++; } else { fail++; console.log(`  FAIL ${what}${extra ? ' — ' + extra : ''}`); } };
const eq = (a, b, what) => ok(Object.is(a, b), what, `got ${JSON.stringify(a)}, want ${JSON.stringify(b)}`);
const near = (a, b, tol, what) => ok(Math.abs(a - b) <= tol, what, `got ${a}, want ${b} +/-${tol}`);

const RATE = 2_000_000;
const dev = (num) => REGISTRY.find(d => d.num === num);

const bytesToBits = (bytes) => {
  const bits = [];
  for (const b of bytes) for (let i = 7; i >= 0; i--) bits.push((b >> i) & 1);
  return bits;
};
const inv = (bits) => bits.map(b => b ^ 1);

/** A single-row BitBuffer from a bit array, the way the r433 device tests build one. */
const rowOf = (bits) => { const bb = new BitBuffer(); for (const v of bits) bb.addBit(v); return bb; };

/**
 * Decode a frame the way the app would: the acuriteTxr decoder inverts the whole buffer before reading, so a
 * frame that reads as `bytes` after the invert must go in inverted. Returns the first emission or undefined.
 */
function decodeFrame(bytes) {
  const d = dev(WEATHER_PROTOCOL);
  const bb = rowOf(inv(bytesToBits(bytes)));
  const out = [];
  d.decode(d, bb, { emit: x => out.push(x) });
  return out[0];
}

/**
 * A local, fully parameterized twin of weatherFrame. With default knobs it must reproduce the real module
 * byte-for-byte — asserted below — after which flipping one knob is a faithful mutation of the encoder.
 * Knobs: tempOffset, tempStep (temperature packing), msgType, humSwap (swap the humidity byte's nibbles),
 * applyParity, checksumBytes (how many bytes the sum covers), corruptChecksum.
 */
function refFrame(s, o = {}) {
  const tempOffset = o.tempOffset ?? 1000, tempStep = o.tempStep ?? 10, msgType = o.msgType ?? 0x04;
  const humSwap = o.humSwap ?? false, applyParity = o.applyParity ?? true;
  const checksumBytes = o.checksumBytes ?? 6, corruptChecksum = o.corruptChecksum ?? false;
  const parity8 = (b) => { const x = (b ^ (b >> 4)) & 0x0f; return (0x6996 >> x) & 1; };
  const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
  const CH = { 1: 0b11, 2: 0b10, 3: 0b00 };

  const id = clamp(Math.round(s.id ?? 0x0abc), 0, 0x3fff);
  const chan = CH[s.channel ?? 1] ?? CH[1];
  const tempRaw = Math.round(clamp(s.tempC, -40, 70) * tempStep) + tempOffset;
  let hb = (s.humidity === undefined ? 127 : clamp(Math.round(s.humidity), 0, 100)) & 0x7f;
  if (humSwap) hb = (((hb << 4) | (hb >> 4)) & 0x7f);
  const battery = (s.battery ?? true) ? 0x40 : 0;

  const bb = [
    (chan << 6) | ((id >> 8) & 0x3f), id & 0xff, battery | msgType, hb,
    (tempRaw >> 7) & 0x7f, tempRaw & 0x7f, 0,
  ];
  if (applyParity) for (let i = 2; i <= 5; i++) if (parity8(bb[i])) bb[i] |= 0x80;
  let sum = 0;
  for (let i = 0; i < checksumBytes; i++) sum += bb[i];
  bb[6] = sum & 0xff;
  if (corruptChecksum) bb[6] ^= 0x01;
  return bb;
}

/** Whether a spec built with `knobs` fails to read back what was asked: absent, or wrong on any field. */
function mismatches(spec, knobs) {
  const d = decodeFrame(refFrame(spec, knobs));
  if (!d) return true;
  const wantHum = spec.humidity === undefined ? undefined : Math.round(spec.humidity);
  return d.model !== WEATHER_MODEL
    || Math.abs(d.temperature_C - Math.max(-40, Math.min(70, spec.tempC))) > 0.05
    || d.humidity !== wantHum;
}

/**
 * A parameterized twin of weatherPulses, for the pulse-side mutations. swapMarks encodes 1/0 with the wrong
 * mark length; dropGap omits the inter-frame gap that separates repeats.
 */
function refPulses(s, rate, o = {}) {
  const swapMarks = o.swapMarks ?? false, dropGap = o.dropGap ?? false;
  const us = (t) => Math.round((t * rate) / 1e6);
  const bits = bytesToBits(weatherFrame(s));
  const longMark = swapMarks ? us(220) : us(408), shortMark = swapMarks ? us(408) : us(220);
  const out = [];
  for (let rep = 0; rep < 3; rep++) {
    for (let i = 0; i < 4; i++) { out.push([true, us(620)]); out.push([false, us(596)]); }
    for (const bit of bits) {
      if (bit) { out.push([true, longMark]); out.push([false, us(204)]); }
      else { out.push([true, shortMark]); out.push([false, us(392)]); }
    }
    if (!dropGap) out.push([false, us(2192)]);
  }
  return out;
}

/** Decode a pulse list back into frames of bits: long mark -> 1, short mark -> 0, sync skipped, big gap ends a frame. */
function pulsesToFrames(pulses, rate) {
  const frames = [];
  let cur = [];
  for (const [level, samples] of pulses) {
    const microseconds = (samples * 1e6) / rate;
    if (level) {
      if (microseconds > 500) continue;                     // a sync mark, not a data bit
      cur.push(microseconds > 314 ? 1 : 0);                 // (220 + 408) / 2 = 314 is the short/long boundary
    } else if (microseconds > 1000) {                       // an inter-frame gap, far longer than any bit gap
      if (cur.length) { frames.push(cur); cur = []; }
    }
  }
  if (cur.length) frames.push(cur);
  return frames;
}

/** Run a pulse list through the app's own PWM slicer and decoder, exactly as the receiver would. */
function decodePulses(pulses, rate) {
  // Every mark is immediately followed by its own gap in this encoding, so pair them into PulseData.
  const marks = [], gaps = [];
  for (let i = 0; i < pulses.length; i++) {
    if (pulses[i][0]) { marks.push(pulses[i][1]); gaps.push((i + 1 < pulses.length && !pulses[i + 1][0]) ? pulses[i + 1][1] : 0); }
  }
  const pd = { pulse: Int32Array.from(marks), gap: Int32Array.from(gaps), numPulses: marks.length, sampleRate: rate, fsk: false };
  const d = dev(WEATHER_PROTOCOL);
  const heard = [];
  pulseSlicerPwm(pd, d, (bits) => {
    let n = 0;
    try { n = d.decode(d, bits, { emit: x => heard.push(x) }); } catch { n = 0; }
    bits.clear();
    return n > 0 ? n : 0;
  });
  return heard;
}

console.log(`Spoofed weather-sensor transmit encoder (round-trip through ${WEATHER_MODEL}, protocol ${WEATHER_PROTOCOL})`);

// ---- The exported constants ----
eq(WEATHER_MODEL, 'Acurite-Tower', 'targets the Acurite Tower model');
eq(WEATHER_PROTOCOL, 40, 'targets rtl_433 protocol number 40');
eq(WEATHER_FREQ_HZ, 433_920_000, 'transmits on the 433.92 MHz band');
ok(!!dev(WEATHER_PROTOCOL), 'the target decoder is registered');

// ---- The reference twin reproduces the real encoder, so the mutations below are meaningful ----
{
  const specs = [
    { tempC: 23.7, humidity: 47 },
    { id: 0x1abc, channel: 2, tempC: -10.5, humidity: 88 },
    { channel: 3, tempC: 0, humidity: 0, battery: false },
  ];
  for (const s of specs) {
    const a = weatherFrame(s), b = refFrame(s);
    ok(a.length === b.length && a.every((v, i) => v === b[i]),
      `reference reproduces weatherFrame byte-for-byte ${JSON.stringify(s)}`, `${a} vs ${b}`);
  }
  const p = weatherPulses(specs[0], RATE), q = refPulses(specs[0], RATE);
  ok(p.length === q.length && p.every((v, i) => v[0] === q[i][0] && v[1] === q[i][1]),
    'reference reproduces weatherPulses element-for-element');
}

// ---- Happy path: a spread of temperatures and humidities all read back ----
{
  const cases = [
    { tempC: 0, humidity: 50, desc: 'freezing point, mid humidity' },
    { tempC: -12.3, humidity: 99, desc: 'a cold negative fraction, high humidity' },
    { tempC: -40, humidity: 0, desc: 'the cold end of range, dry' },
    { tempC: 45, humidity: 30, desc: 'a hot 45 C' },
    { tempC: 60, humidity: 72, desc: 'a silly-hot 60 C, still in range' },
    { tempC: 23.7, humidity: 47, desc: 'a comfortable room' },
  ];
  for (const c of cases) {
    const d = decodeFrame(weatherFrame(c));
    ok(!!d, `decodes: ${c.desc}`, JSON.stringify(c));
    if (d) {
      eq(d.model, WEATHER_MODEL, `  model: ${c.desc}`);
      near(d.temperature_C, c.tempC, 0.05, `  temperature at 0.1 C: ${c.desc}`);
      eq(d.humidity, c.humidity, `  humidity: ${c.desc}`);
    }
  }
}

// ---- Clamping: out-of-range temperature and humidity are pinned to what the encoding can carry ----
{
  const hot = decodeFrame(weatherFrame({ tempC: 100, humidity: 50 }));
  eq(hot?.temperature_C, 70, 'a 100 C request is clamped to the decoder ceiling of 70 C');
  const cold = decodeFrame(weatherFrame({ tempC: -60, humidity: 50 }));
  eq(cold?.temperature_C, -40, 'a -60 C request is clamped to the floor of -40 C');
  const wet = decodeFrame(weatherFrame({ tempC: 20, humidity: 150 }));
  eq(wet?.humidity, 100, 'a 150 % humidity request is clamped to 100 %');
}

// ---- Channel and battery survive ----
{
  for (const [n, letter] of [[1, 'A'], [2, 'B'], [3, 'C']]) {
    eq(decodeFrame(weatherFrame({ channel: n, tempC: 20, humidity: 40 }))?.channel, letter, `channel ${n} reads as '${letter}'`);
  }
  eq(decodeFrame(weatherFrame({ tempC: 20, humidity: 40, battery: true }))?.battery_ok, 1, 'battery good reads as ok');
  eq(decodeFrame(weatherFrame({ tempC: 20, humidity: 40, battery: false }))?.battery_ok, 0, 'battery flag off reads as low');
}

// ---- Omitting humidity sends the "no element" code, and the decoder reports no humidity ----
{
  const d = decodeFrame(weatherFrame({ tempC: 21 }));
  ok(!!d, 'a temperature-only frame still decodes');
  ok(d && d.humidity === undefined, 'no humidity is reported when none was asked for (byte 3 = 127)');
}

// ---- Premise: the checksum is the decoder's, and one flipped byte is caught ----
{
  const good = weatherFrame({ tempC: 23.7, humidity: 47 });
  ok(!!decodeFrame(good), 'the intact frame decodes (premise)');
  for (const i of [0, 1, 2, 3, 4, 5, 6]) {
    const bad = good.slice(); bad[i] ^= 0x01;
    ok(!decodeFrame(bad), `flipping byte ${i} makes the decoder reject the frame`);
  }
}

// ---- Premise: temperature packs and reads back at 0.1 C, and negative degrees survive ----
{
  // The count is offset by 100 C (1000 tenths), so a negative reading is a smaller positive count, not a sign bit.
  const f = weatherFrame({ tempC: -12.3, humidity: 30 });
  const rawCount = ((f[4] & 0x7f) << 7) | (f[5] & 0x7f);
  eq(rawCount, Math.round(-12.3 * 10) + 1000, 'the temperature count is offset, so -12.3 C packs as 877 (positive)');
  eq(decodeFrame(f)?.temperature_C, -12.3, 'and it reads back as -12.3 C');
  // 0.1 C resolution: a tenth-degree step changes the count by exactly one.
  const a = ((x) => ((x[4] & 0x7f) << 7) | (x[5] & 0x7f))(weatherFrame({ tempC: 19.0, humidity: 30 }));
  const b = ((x) => ((x[4] & 0x7f) << 7) | (x[5] & 0x7f))(weatherFrame({ tempC: 19.1, humidity: 30 }));
  eq(b - a, 1, 'a 0.1 C step is one count: the field carries tenths');
}

// ---- Premise: weatherPulses short vs long marks match the frame bits ----
{
  const spec = { tempC: 23.7, humidity: 47, channel: 2 };
  const frames = pulsesToFrames(weatherPulses(spec, RATE), RATE);
  const wantBits = bytesToBits(weatherFrame(spec));
  eq(frames.length, 3, 'the frame is repeated three times, as the sensor does');
  let allMatch = frames.length > 0;
  for (const fr of frames) {
    if (fr.length !== wantBits.length || !fr.every((v, i) => v === wantBits[i])) allMatch = false;
  }
  ok(allMatch, 'every repeat decodes (long mark -> 1, short mark -> 0) back to the exact frame bits');

  // The inter-frame gap must be present and far longer than any bit gap (which top out at 392 us).
  const gapUs = weatherPulses(spec, RATE).filter(([lvl]) => !lvl).map(([, n]) => (n * 1e6) / RATE);
  ok(gapUs.some(g => g > 1000), 'an inter-frame gap well beyond any bit gap is present');
  ok(gapUs.filter(g => g > 1000).length === 3, 'exactly one inter-frame gap per repeat');
}

// ---- Layer 2: the pulses decode through the app's OWN slicer and decoder ----
{
  const spec = { tempC: 45, humidity: 88, channel: 3 };
  const heard = decodePulses(weatherPulses(spec, RATE), RATE);
  const d = heard.find(x => x.model === WEATHER_MODEL);
  ok(!!d, 'the OOK pulses decode through pulseSlicerPwm + acuriteTxr', JSON.stringify(heard.slice(0, 2)));
  if (d) {
    near(d.temperature_C, 45, 0.05, '  temperature survives the pulse slicer');
    eq(d.humidity, 88, '  humidity survives the pulse slicer');
    eq(d.channel, 'C', '  channel survives the pulse slicer');
  }
}

// ---- Mutation battery: each faithful mutation of the encoder must break the round trip ----
{
  const spec = { tempC: 23.7, humidity: 50, channel: 2 };
  ok(!mismatches(spec, {}), 'the reference build with correct knobs decodes correctly (control)');

  // Frame-side mutations, decoded through the frame path.
  ok(mismatches(spec, { corruptChecksum: true }), 'mutation caught: wrong checksum');
  ok(mismatches(spec, { checksumBytes: 5 }), 'mutation caught: checksum over the wrong number of bytes');
  ok(mismatches(spec, { applyParity: false }), 'mutation caught: parity bits not set');
  ok(mismatches(spec, { tempOffset: 400 }), 'mutation caught: wrong temperature offset');
  ok(mismatches(spec, { tempStep: 5 }), 'mutation caught: wrong temperature scale');
  ok(mismatches(spec, { humSwap: true }), 'mutation caught: humidity nibbles swapped');
  ok(mismatches(spec, { msgType: 0x05 }), 'mutation caught: wrong message type');

  // Pulse-side mutations, decoded through the pulse path.
  const wantBits = bytesToBits(weatherFrame(spec));
  const framesEqual = (pulses) => {
    const frames = pulsesToFrames(pulses, RATE);
    return frames.length === 3 && frames.every(fr => fr.length === wantBits.length && fr.every((v, i) => v === wantBits[i]));
  };
  ok(framesEqual(refPulses(spec, RATE)), 'the reference pulses decode correctly (control)');
  ok(!framesEqual(refPulses(spec, RATE, { swapMarks: true })), 'mutation caught: short/long marks swapped in the PWM');
  ok(!framesEqual(refPulses(spec, RATE, { dropGap: true })), 'mutation caught: missing inter-frame gap');
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
